def solve(s: str) -> int:
    char_counts = {}
    left = 0
    max_len = 0

    for right, char in enumerate(s):
        char_counts[char] = char_counts.get(char, 0) + 1

        while len(char_counts) > 2:
            left_char = s[left]
            char_counts[left_char] -= 1
            if char_counts[left_char] == 0:
                del char_counts[left_char]
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len
