// @function Calculates distance in ATRs from close to the nearest 20-bar swing high above or swing low below.
// @param highs Series of high prices.
// @param lows Series of low prices.
// @param atr Series of ATR values.
// @returns Distance to the nearest qualifying swing level in ATR units as a float.
f_room(series float highs, series float lows, series float atr) =>
    float sh = ta.highest(highs, 20)
    float sl = ta.lowest(lows, 20)

    float dist_high = sh > close and atr > 0 ? (sh - close) / atr : na
    float dist_low  = sl < close and atr > 0 ? (close - sl) / atr : na

    not na(dist_high) and not na(dist_low) ? math.min(dist_high, dist_low) : not na(dist_high) ? dist_high : dist_low
